func (this *Tracker) TransparentProc(hwnd int64, msg int64, wParam int64, lParam int64) int64 {
	switch int32(msg) {
	case win32.OSWM_NCHITTEST:
		if this.inEvent {
			return int64(win32.OSHTTRANSPARENT)
		}
		break
	case win32.OSWM_SETCURSOR:
		if this.clientCursor != (nil) {
			var cond844 int32
			if this.parent != (nil) {
				cond844 = this.parent.GetShellZoom()
			} else {
				cond844 = this.NativeZoom
			}
			win32.OSSetCursor(CursorWin32_getHandle(this.clientCursor, DPIUtilGetZoomForAutoscaleProperty(cond844)))
			return int64(1)
		}
		if this.resizeCursor != 0 {
			win32.OSSetCursor(this.resizeCursor)
			return int64(1)
		}
		break
	case win32.OSWM_PAINT:
		if this.hwndOpaque == hwnd {
			var ps *win32.PAINTSTRUCT = win32.NewPAINTSTRUCT()
			var hDC int64 = win32.OSBeginPaint(hwnd, ps)
			var hBitmap int64 = int64(0)
			var hBrush int64 = int64(0)
			var oldBrush int64 = int64(0)
			var transparentBrush int64 = win32.OSCreateSolidBrush(0xFFFFFF)
			oldBrush = win32.OSSelectObject(hDC, transparentBrush)
			win32.OSPatBlt(hDC, ps.Left, ps.Top, ps.Right-ps.Left, ps.Bottom-ps.Top, win32.OSPATCOPY)
			win32.OSSelectObject(hDC, oldBrush)
			win32.OSDeleteObject(transparentBrush)
			var bandWidth int32 = 1
			if this.stippled {
				bandWidth = 3
				var bits []int8 = []int8{int8(-86), int8(0), int8(85), int8(0), int8(-86), int8(0), int8(85), int8(0), int8(-86), int8(0), int8(85), int8(0), int8(-86), int8(0), int8(85), int8(0)}
				hBitmap = win32.OSCreateBitmap(8, 8, 1, 1, bits)
				hBrush = win32.OSCreatePatternBrush(hBitmap)
				oldBrush = win32.OSSelectObject(hDC, hBrush)
				win32.OSSetBkColor(hDC, 0xF0F0F0)
			} else {
				oldBrush = win32.OSSelectObject(hDC, win32.OSGetStockObject(win32.OSBLACK_BRUSH))
			}
			var rect1 *win32.RECT = win32.NewRECT()
			for _, rect := range this.rectangles {
				rect1.Left = rect.X
				rect1.Top = rect.Y
				rect1.Right = rect.X + rect.Width
				rect1.Bottom = rect.Y + rect.Height
				win32.OSMapWindowPointsHWndFromHWndToLpPointsCPoints(int64(0), this.hwndOpaque, rect1, 2)
				var width int32 = rect1.Right - rect1.Left
				var height int32 = rect1.Bottom - rect1.Top
				win32.OSPatBlt(hDC, rect1.Left, rect1.Top, width, bandWidth, win32.OSPATCOPY)
				win32.OSPatBlt(hDC, rect1.Left, rect1.Top+bandWidth, bandWidth, height-(bandWidth*2), win32.OSPATCOPY)
				win32.OSPatBlt(hDC, rect1.Right-bandWidth, rect1.Top+bandWidth, bandWidth, height-(bandWidth*2), win32.OSPATCOPY)
				win32.OSPatBlt(hDC, rect1.Left, rect1.Bottom-bandWidth, width, bandWidth, win32.OSPATCOPY)
			}
			win32.OSSelectObject(hDC, oldBrush)
			if this.stippled {
				win32.OSDeleteObject(hBrush)
				win32.OSDeleteObject(hBitmap)
			}
			win32.OSEndPaint(hwnd, ps)
			if !this.drawn {
				win32.OSSetLayeredWindowAttributes(this.hwndOpaque, 0xFFFFFF, int8(-1), win32.OSLWA_COLORKEY|win32.OSLWA_ALPHA)
				this.drawn = true
			}
			return int64(0)
		}
	}
	var cond845 int64
	if hwnd == this.hwndTransparent {
		cond845 = this.oldTransparentProc
	} else {
		cond845 = this.oldOpaqueProc
	}
	return win32.OSCallWindowProc(cond845, hwnd, int32(msg), wParam, lParam)
}

func (this *Tracker) Update() {
	if this.hwndOpaque != 0 {
		return
	}
	if this.parent != (nil) {
		if this.parent.IsDisposed() {
			return
		}
		var shell *Shell = this.parent.impl.getShell_()
		shell.impl.updateAll_(true)
	} else {
		this.display.Update()
	}
}

func (this *Tracker) wmKeyDown_(hwnd int64, wParam int64, lParam int64) *win32.LRESULT {
	var result *win32.LRESULT = this.Widget.wmKeyDown_(hwnd, wParam, lParam)
	if result != (nil) {
		return result
	}
	var isMirrored bool = this.parent != (nil) && (this.parent.style&MIRRORED) != 0
	var stepSize int32
	if int32(win32.OSGetKeyState(win32.OSVK_CONTROL)) < 0 {
		stepSize = TrackerSTEPSIZE_SMALL
	} else {
		stepSize = TrackerSTEPSIZE_LARGE
	}
	var xChange int32 = 0
	var yChange int32 = 0
	switch int32(wParam) {
	case win32.OSVK_ESCAPE:
		this.cancelled = true
		this.tracking = false
		break
	case win32.OSVK_RETURN:
		this.tracking = false
		break
	case win32.OSVK_LEFT:
		if isMirrored {
			xChange = stepSize
		} else {
			xChange = -stepSize
		}
		break
	case win32.OSVK_RIGHT:
		if isMirrored {
			xChange = -stepSize
		} else {
			xChange = stepSize
		}
		break
	case win32.OSVK_UP:
		yChange = -stepSize
		break
	case win32.OSVK_DOWN:
		yChange = stepSize
		break
	}
	if xChange != 0 || yChange != 0 {
		var oldRectangles []*Rectangle = this.rectangles
		var oldStippled bool = this.stippled
		var rectsToErase []*Rectangle = make([]*Rectangle, int32(len(this.rectangles)))
		for i := int32(0); i < int32(len(this.rectangles)); i++ {
			var current *Rectangle = this.rectangles[i]
			rectsToErase[i] = NewRectangle(current.X, current.Y, current.Width, current.Height)
		}
		var event *Event = NewEvent()
		var newLocationInPoints *Point = this.display.TranslateFromDisplayCoordinates(NewPoint(this.oldX+xChange, this.oldY+yChange))
		event.SetLocation(newLocationInPoints.X, newLocationInPoints.Y)
		var cursorPos *Point
		if (this.style & RESIZE) != 0 {
			this.ResizeRectangles(xChange, yChange)
			this.inEvent = true
			this.SendEventEventTypeEvent(Resize, event)
			this.inEvent = false
			if this.IsDisposed() {
				this.cancelled = true
				return win32.LRESULTONE
			}
			var draw bool = false
			if !slices.Equal(this.rectangles, oldRectangles) {
				var length int32 = int32(len(this.rectangles))
				if length != int32(len(rectsToErase)) {
					draw = true
				} else {
					for i := int32(0); i < length; i++ {
						if !this.rectangles[i].Equals(rectsToErase[i]) {
							draw = true
							break
						}
					}
				}
			} else {
				draw = true
			}
			if draw {
				this.DrawRectangles(rectsToErase, oldStippled)
				this.Update()
				this.DrawRectangles(this.rectangles, this.stippled)
			}
			cursorPos = this.AdjustResizeCursor()
		} else {
			this.MoveRectangles(xChange, yChange)
			this.inEvent = true
			this.SendEventEventTypeEvent(Move, event)
			this.inEvent = false
			if this.IsDisposed() {
				this.cancelled = true
				return win32.LRESULTONE
			}
			var draw bool = false
			if !slices.Equal(this.rectangles, oldRectangles) {
				var length int32 = int32(len(this.rectangles))
				if length != int32(len(rectsToErase)) {
					draw = true
				} else {
					for i := int32(0); i < length; i++ {
						if !this.rectangles[i].Equals(rectsToErase[i]) {
							draw = true
							break
						}
					}
				}
			} else {
				draw = true
			}
			if draw {
				this.DrawRectangles(rectsToErase, oldStippled)
				this.Update()
				this.DrawRectangles(this.rectangles, this.stippled)
			}
			cursorPos = this.AdjustMoveCursor()
		}
		if cursorPos != (nil) {
			this.oldX = cursorPos.X
			this.oldY = cursorPos.Y
		}
	}
	return result
}

func (this *Tracker) wmSysKeyDown_(hwnd int64, wParam int64, lParam int64) *win32.LRESULT {
	var result *win32.LRESULT = this.Widget.wmSysKeyDown_(hwnd, wParam, lParam)
	if result != (nil) {
		return result
	}
	this.cancelled = true
	this.tracking = false
	return result
}

func (this *Tracker) WmMouse(message int32, wParam int64, lParam int64) *win32.LRESULT {
	var isMirrored bool = this.parent != (nil) && (this.parent.style&MIRRORED) != 0
	var newPos int32 = win32.OSGetMessagePos()
	var newX int32 = win32.OSGET_X_LPARAM(int64(newPos))
	var newY int32 = win32.OSGET_Y_LPARAM(int64(newPos))
	if newX != this.oldX || newY != this.oldY {
		var oldRectangles []*Rectangle = this.rectangles
		var oldStippled bool = this.stippled
		var rectsToErase []*Rectangle = make([]*Rectangle, int32(len(this.rectangles)))
		for i := int32(0); i < int32(len(this.rectangles)); i++ {
			var current *Rectangle = this.rectangles[i]
			rectsToErase[i] = NewRectangle(current.X, current.Y, current.Width, current.Height)
		}
		var event *Event = NewEvent()
		var newLocationInPoints *Point = this.display.TranslateFromDisplayCoordinates(NewPoint(newX, newY))
		event.SetLocation(newLocationInPoints.X, newLocationInPoints.Y)
		if (this.style & RESIZE) != 0 {
			if isMirrored {
				this.ResizeRectangles(this.oldX-newX, newY-this.oldY)
			} else {
				this.ResizeRectangles(newX-this.oldX, newY-this.oldY)
			}
			this.inEvent = true
			this.SendEventEventTypeEvent(Resize, event)
			this.inEvent = false
			if this.IsDisposed() {
				this.cancelled = true
				return win32.LRESULTONE
			}
			var draw bool = false
			if !slices.Equal(this.rectangles, oldRectangles) {
				var length int32 = int32(len(this.rectangles))
				if length != int32(len(rectsToErase)) {
					draw = true
				} else {
					for i := int32(0); i < length; i++ {
						if !this.rectangles[i].Equals(rectsToErase[i]) {
							draw = true
							break
						}
					}
				}
			} else {
				draw = true
			}
			if draw {
				this.DrawRectangles(rectsToErase, oldStippled)
				this.Update()
				this.DrawRectangles(this.rectangles, this.stippled)
			}
			var cursorPos *Point = this.AdjustResizeCursor()
			if cursorPos != (nil) {
				newX = cursorPos.X
				newY = cursorPos.Y
			}
		} else {
			if isMirrored {
				this.MoveRectangles(this.oldX-newX, newY-this.oldY)
			} else {
				this.MoveRectangles(newX-this.oldX, newY-this.oldY)
			}
			this.inEvent = true
			this.SendEventEventTypeEvent(Move, event)
			this.inEvent = false
			if this.IsDisposed() {
				this.cancelled = true
				return win32.LRESULTONE
			}
			var draw bool = false
			if !slices.Equal(this.rectangles, oldRectangles) {
				var length int32 = int32(len(this.rectangles))
				if length != int32(len(rectsToErase)) {
					draw = true
				} else {
					for i := int32(0); i < length; i++ {
						if !this.rectangles[i].Equals(rectsToErase[i]) {
							draw = true
							break
						}
					}
				}
			} else {
				draw = true
			}
			if draw {
				this.DrawRectangles(rectsToErase, oldStippled)
				this.Update()
				this.DrawRectangles(this.rectangles, this.stippled)
			}
		}
		this.oldX = newX
		this.oldY = newY
	}
	this.tracking = message != win32.OSWM_LBUTTONUP
	return nil
}

func TrackerCheckStyle(style int32) int32 {
	if (style & (LEFT | RIGHT | UP | DOWN)) == 0 {
		style |= LEFT | RIGHT | UP | DOWN
	}
	return style
}
